 "content": "from collections import Counter

def transform(grid):
    """Restore the cells hidden by 2 using the grid's dihedral symmetry."""
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if src[r][c] != 2:
                continue
            # The picture is symmetric across both diagonals and both mid-axes.
            orbit = {
                (r, c), (h - 1 - r, c), (r, w - 1 - c),
                (h - 1 - r, w - 1 - c),
                (c, r), (h - 1 - c, r), (c, w - 1 - r),
                (h - 1 - c, w - 1 - r),
            }
            values = [src[a][b] for a, b in orbit
                      if 0 <= a < h and 0 <= b < w and src[a][b] != 2]
            if not values:
                raise ValueError(f"No visible symmetric source for {(r, c)}")
            out[r][c] = Counter(values).most_common(1)[0][0]
    return out
